import { afterEach, describe, expect, it } from "vitest";

import {
	mappedLaneTargets,
	parseWorkflowLaneExecutions,
	validateWorkflowAggregate,
	validateWorkflowProjections,
} from "./workflow-projections.mjs";
import type { ValidationLanes } from "./workflow-projections.mjs";

const lanes: ValidationLanes = {
	lanes: [
		{
			id: "unit",
			nxTarget: "test:unit",
			mappingStatus: "mapped",
			runtimes: ["node-24", "node-26"],
		},
		{
			id: "stdio",
			nxTarget: "test:stdio",
			mappingStatus: "mapped",
			runtimes: ["node-24"],
		},
		{
			id: "external",
			nxTarget: null,
			mappingStatus: "external",
			runtimes: ["node-24"],
		},
	],
	aggregates: {
		"pull-request-ci": {
			lanes: ["unit", "stdio"],
		},
	},
};

const workflow = `
jobs:
  build:
    strategy:
      matrix:
        node-version: ["24.x", "26.x"]
    steps:
      - name: Set up Node.js
        uses: actions/setup-node@test
        with:
          node-version: \${{ matrix.node-version }}
      - name: Unit Node 24
        if: matrix.node-version == '24.x'
        run: npx nx run repository:test:unit -- --coverage
      - name: Unit Node 26
        if: matrix.node-version == '26.x'
        run: npx nx run repository:test:unit -- --coverage
      - name: Stdio
        if: matrix.node-version == '24.x'
        run: npx nx run repository:test:stdio
`;

const runManyWorkflow = `
jobs:
  build:
    strategy:
      matrix:
        node-version: ["24.x", "26.x"]
    steps:
      - name: Set up Node.js
        uses: actions/setup-node@test
        with:
          node-version: \${{ matrix.node-version }}
      - name: Validate Node 24
        if: \${{ !cancelled() && matrix.node-version == '24.x' }}
        run: npx nx run-many --projects=repository --targets=test:unit,test:stdio --parallel=3 --outputStyle=stream
      - name: Validate Node 26
        if: \${{ !cancelled() && matrix.node-version == '26.x' }}
        run: npx nx run-many -p repository -t test:unit --parallel=3 --outputStyle=stream
`;

function expectFailure(callback: () => unknown, pattern: RegExp) {
	expect(callback).toThrow(pattern);
}

function validate(source = workflow) {
	return validateWorkflowAggregate(source, {
		lanes,
		aggregateId: "pull-request-ci",
		expectedJobs: "build",
		label: "fixture workflow",
	});
}

